{
  "name": "@jumpmaster/opencode-throughput",
  "version": "2.2.0",
  "description": "Real-time LLM performance monitoring plugin for OpenCode. Tracks TTFT, TPS, latency, token usage and cost per model with a TUI sidebar display.",
  "type": "module",
  "exports": {
    ".": "./dist/index.js",
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "verify": "bun run scripts/verify.ts",
    "release": "bun run scripts/release.ts",
    "prepublishOnly": "bun run build && bun run typecheck && bun test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "llm",
    "throughput",
    "latency",
    "ttft",
    "tps",
    "monitoring",
    "performance"
  ],
  "license": "MIT",
  "engines": {
    "opencode": ">=1.18.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.18",
    "@opentui/core": ">=0.1.97",
    "@opentui/solid": ">=0.1.97",
    "solid-js": "^1.9.11"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.18",
    "@opencode/plugin": "^2.0.7",
    "@opentui/core": "^0.5.11",
    "@opentui/solid": "^0.5.11",
    "@types/bun": "^1.4.2",
    "@types/node": "^25.5.0",
    "solid-js": "^1.9.15",
    "typescript": "^5.7.0"
  }
}
